import React from 'react';
import { CheckCircle2, Plus } from 'lucide-react';

const ProductionTimeline = ({ milestones, tasks }) => {
  // Colors from the main app
  const colors = {
    primary: '#f7abff',
    secondary: '#2f2a2f',
    accent: '#3CDFFF',
    darkAccent: '#620f87',
    light: '#f9f9f9',
    midGray: '#797979',
    successGreen: '#4ADE80',
    warningOrange: '#F97316',
    errorRed: '#EF4444'
  };

  // Calculate completion for each milestone
  const calculateMilestoneProgress = (milestoneName) => {
    const milestoneTasks = tasks.filter(task => task.milestone === milestoneName);
    const totalTasks = milestoneTasks.length;
    const completedTasks = milestoneTasks.filter(task => task.completed).length;
    return totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
  };

  // Calculate overall project progress
  const calculateOverallProgress = () => {
    if (tasks.length === 0) return 0;
    const completedTasks = tasks.filter(task => task.completed).length;
    return Math.round((completedTasks / tasks.length) * 100);
  };

  // Get the position of the "You are here" indicator
  const getTimelinePosition = () => {
    const activeMilestone = milestones.find(m => m.active);
    if (!activeMilestone) return 0;

    const activeMilestoneIndex = milestones.findIndex(m => m.active);
    const milestoneWidth = 100 / milestones.length;
    const basePosition = activeMilestoneIndex * milestoneWidth;
    
    // Add progress within the current milestone
    const milestoneProgress = calculateMilestoneProgress(activeMilestone.name);
    const progressWithinMilestone = (milestoneProgress * milestoneWidth) / 100;
    
    return Math.min(basePosition + progressWithinMilestone, 100);
  };

  const overallProgress = calculateOverallProgress();
  const timelinePosition = getTimelinePosition();

  // Format date
  const formatDate = (date) => {
    if (!date) return "TBD";
    const options = { year: 'numeric', month: 'short', day: 'numeric' };
    return new Date(date).toLocaleDateString(undefined, options);
  };

  return (
    <div className="w-full">
      {/* Single Clean Timeline */}
      <div className="mb-8 relative">
        {/* Main timeline bar */}
        <div className="h-6 bg-gray-800 rounded-full overflow-hidden shadow-inner relative">
          {/* Milestone sections */}
          {milestones.sort((a, b) => a.order - b.order).map((milestone, index) => {
            const sectionWidth = 100 / milestones.length;
            const left = index * sectionWidth;
            const progress = calculateMilestoneProgress(milestone.name);
            
            return (
              <div
                key={milestone.id}
                className="absolute top-0 h-full flex items-center justify-center"
                style={{
                  left: `${left}%`,
                  width: `${sectionWidth}%`,
                  background: milestone.completed 
                    ? 'linear-gradient(135deg, #4ADE80, #22c55e)'
                    : milestone.active
                      ? 'linear-gradient(135deg, #EC4899, #be185d)'
                      : 'rgba(75, 75, 75, 0.3)',
                  borderRight: index < milestones.length - 1 ? '1px solid rgba(255,255,255,0.1)' : 'none'
                }}
              >
                {/* Progress fill within milestone */}
                <div 
                  className="absolute left-0 top-0 h-full rounded-r-full opacity-60"
                  style={{
                    width: `${progress}%`,
                    background: milestone.active 
                      ? 'linear-gradient(135deg, #f472b6, #ec4899)'
                      : 'linear-gradient(135deg, #60a5fa, #3b82f6)'
                  }}
                />
                
                {/* Milestone icon */}
                <div className={`
                  w-4 h-4 rounded-full flex items-center justify-center text-white text-xs font-bold relative z-10
                  ${milestone.completed ? 'bg-green-500' : milestone.active ? 'bg-pink-500' : 'bg-gray-600'}
                `}>
                  {milestone.completed ? <CheckCircle2 className="h-3 w-3" /> : index + 1}
                </div>
              </div>
            );
          })}
          
          {/* "You are here" indicator */}
          <div
            className="absolute top-1/2 transform -translate-y-1/2 w-2 h-2 rounded-full bg-white z-20 transition-all duration-500"
            style={{
              left: `${timelinePosition}%`,
              boxShadow: '0 0 10px rgba(255,255,255,0.8)'
            }}
          >
            <div className="absolute inset-0 rounded-full bg-white animate-ping opacity-75"></div>
          </div>
        </div>

        {/* Milestone labels */}
        <div className="flex justify-between mt-4">
          {milestones.sort((a, b) => a.order - b.order).map((milestone) => (
            <div key={milestone.id} className="text-center flex-1">
              <div className={`font-medium transition-colors ${
                milestone.active ? 'text-pink-400' : 'text-white'
              }`}>
                {milestone.name}
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {formatDate(milestone.targetDate)}
              </div>
              <div className="text-xs text-gray-500 mt-1">
                {Math.round(calculateMilestoneProgress(milestone.name))}% Complete
              </div>
            </div>
          ))}
        </div>

        {/* Overall progress indicator */}
        <div className="text-center mt-6">
          <div className="inline-block px-4 py-2 rounded-full bg-gray-800 text-white shadow-lg">
            <span className="text-lg font-bold">{overallProgress}%</span>
            <span className="text-gray-400 ml-2">Overall Progress</span>
          </div>
        </div>
      </div>

      {/* Milestone Task Sections (keeping the bottom sections) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {milestones.sort((a, b) => a.order - b.order).map(milestone => (
          <div 
            key={milestone.id}
            className={`
              bg-gray-800 rounded-lg overflow-hidden transition-all shadow-lg
              ${milestone.active ? 'ring-2 ring-pink-500 ring-opacity-50' : ''}
            `}
          >
            {/* Milestone header */}
            <div 
              className={`p-4 border-b border-gray-700 flex justify-between items-center
                ${milestone.active 
                  ? 'bg-gradient-to-r from-pink-900/40 to-pink-800/20' 
                  : milestone.completed
                    ? 'bg-gradient-to-r from-green-900/40 to-green-800/20'
                    : 'bg-gray-900/50'
                }
              `}
            >
              <div>
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                  {milestone.active && <div className="w-2 h-2 rounded-full bg-pink-500 animate-pulse"></div>}
                  {milestone.name}
                </h3>
                <p className="text-sm text-gray-400 mt-1">{milestone.description}</p>
              </div>
              <button 
                className="p-2 rounded-full bg-pink-600/80 hover:bg-pink-700 transition-all shadow-lg"
                onClick={() => {
                  // You can add logic here to switch to tasks tab or open task creation
                  console.log(`Add task to ${milestone.name}`);
                }}
              >
                <Plus className="h-4 w-4 text-white" />
              </button>
            </div>
            
            {/* Tasks list */}
            <div className="p-4 max-h-64 overflow-y-auto">
              <div className="space-y-2">
                {tasks
                  .filter(task => task.milestone === milestone.name)
                  .sort((a, b) => a.completed === b.completed ? 0 : a.completed ? 1 : -1)
                  .slice(0, 5)
                  .map(task => (
                    <div 
                      key={task.id}
                      className={`
                        flex items-center p-3 rounded-lg transition-all
                        ${task.completed 
                          ? 'bg-gray-900/50 hover:bg-gray-800/70' 
                          : 'bg-gray-800/80 hover:bg-gray-700/80 shadow-md'
                        }
                      `}
                    >
                      <div 
                        className="cursor-pointer mr-3 flex-shrink-0 transition-all"
                        onClick={() => {
                          // Toggle task completion
                          console.log(`Toggle task ${task.id}`);
                        }}
                      >
                        {task.completed ? 
                          <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center transition-all shadow-md">
                            <CheckCircle2 className="h-3 w-3 text-white" />
                          </div> : 
                          <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white transition-all" />
                        }
                      </div>
                      <div className={`flex-grow ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                        {task.name}
                      </div>
                    </div>
                  ))}
                
                {tasks.filter(task => task.milestone === milestone.name).length === 0 && (
                  <div className="text-center text-gray-500 py-6 px-4 bg-gray-900/40 rounded-lg">
                    <div className="text-sm">No tasks for this milestone yet</div>
                    <div className="text-xs text-yellow-500/70 mt-1">Ready to get started!</div>
                  </div>
                )}
                
                {tasks.filter(task => task.milestone === milestone.name).length > 5 && (
                  <button
                    onClick={() => {
                      // Navigate to tasks view
                      console.log(`View all tasks for ${milestone.name}`);
                    }}
                    className="w-full py-2 mt-2 text-center text-gray-400 hover:text-white rounded-lg bg-gray-900/50 hover:bg-gray-700/50 transition-all text-sm"
                  >
                    View {tasks.filter(task => task.milestone === milestone.name).length - 5} more tasks
                  </button>
                )}
              </div>
            </div>
            
            {/* Milestone footer */}
            <div className="p-3 border-t border-gray-800 bg-gray-900/50 flex justify-between text-xs text-gray-400">
              <div>Target: {formatDate(milestone.targetDate)}</div>
              <div>
                {tasks.filter(task => task.milestone === milestone.name && task.completed).length} / {tasks.filter(task => task.milestone === milestone.name).length} tasks
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ProductionTimeline;
